def verify():
    a = RE + 550e3; T = 2 * math.pi * math.sqrt(a ** 3 / MU); assert abs(T / 60 - 95.5) < 0.3
    ag = (MU * (86164 / (2 * math.pi)) ** 2) ** (1 / 3); assert abs((ag - RE) / 1e3 - 35786) < 20
    assert abs(2 * 35786 / 3e5 * 1e3 - 238.6) < 0.2
    L = 20 * math.log10(36000) + 20 * math.log10(12000) + 32.44; assert abs(L - 205.15) < 0.02
    assert abs(50 - 205 + 15 + 228.6 - 88.6) < 1e-9 and abs(40 - 10 * math.log10(200) - 16.99) < 0.01
    assert abs(88.6 - 10 * math.log10(36e6) - 13.04) < 0.01 and abs(30 * 3 * 0.75 - 67.5) < 1e-9
    G = 0.6 * (math.pi * 1 / 0.025) ** 2; assert abs(10 * math.log10(G) - 39.77) < 0.02 and abs(35786 / 550 - 65.07) < 0.01


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
